//! What a `build.rs` calls.
//!
//! One directory of `.rsx` in, one directory of `.rs` out, each with its
//! position map beside it. Nothing here knows about cargo: a build script
//! is one caller, and the command-line tool of a later plan will be
//! another.

use std::path::{Path, PathBuf};

use crate::error::CompileError;
use crate::transpile::transpile;

/// Translate every `.rsx` under `from` into a `.rs` under `to`, keeping
/// the directory structure, and write `<name>.rsx.map` beside each one.
///
/// Returns the generated files, in a stable order, so that a build script
/// can print `rerun-if-changed` for each.
pub fn compile_directory(from: &Path, to: &Path) -> Result<Vec<PathBuf>, CompileError> {
    let mut sources = Vec::new();
    collect(from, &mut sources)?;
    sources.sort();

    let mut written = Vec::new();
    for source_path in sources {
        let relative = source_path
            .strip_prefix(from)
            .unwrap_or(&source_path)
            .to_path_buf();
        let target = to.join(relative).with_extension("rs");

        let source = read(&source_path)?;
        let out = transpile(&source).map_err(|error| error.in_file(&source_path))?;

        if let Some(parent) = target.parent() {
            create_dir(parent)?;
        }
        write(&target, &out.rust)?;
        write(&target.with_extension("rsx.map"), &out.map.to_text())?;
        written.push(target);
    }
    Ok(written)
}

/// The same, plus the route table — for an application whose screens
/// are its files.
///
/// Routing is asked for rather than assumed: under `compile_directory` a
/// `page.rsx` is just a file, and an application that mounts its
/// components by hand (the counter, the monitor) keeps doing so. Under
/// this one, every `page.rsx` is a screen and must declare `fn Page`,
/// which is what makes a missing declaration a sentence instead of a
/// screen that never appears.
///
/// The table is written beside the pages it names, so its `include!`
/// paths are the paths they were written as, and an application
/// includes one file rather than one per screen.
pub fn compile_app(from: &Path, to: &Path) -> Result<Vec<PathBuf>, CompileError> {
    let mut written = compile_directory(from, to)?;

    let table = to.join(PAGES);
    write(&table, &crate::routes::table_for(from)?)?;
    written.push(table);

    Ok(written)
}

/// The name of the one file an application includes.
///
/// One name whatever is in it: an application writes `#[rustx::main]`
/// and the attribute includes this, so the two halves agree without the
/// developer ever being told the name.
pub const PAGES: &str = "pages.rs";

/// Every page under `from`, compiled and gathered into `pages.rs` with
/// no route table — for an application that mounts its components by
/// hand.
///
/// The pages are included flat rather than wrapped in modules of their
/// own: what such an application declares in a page it calls from its
/// own code, and a module would hide it.
pub fn compile_pages(from: &Path, to: &Path) -> Result<Vec<PathBuf>, CompileError> {
    let written = compile_directory(from, to)?;

    let mut text =
        String::from("// Generated by rustx from the pages in `app/`. Nobody edits this file.\n\n");
    for page in &written {
        if page.extension().is_some_and(|extension| extension == "rs") {
            let relative = page.strip_prefix(to).unwrap_or(page);
            text.push_str(&format!(
                "include!(\"{}\");\n",
                relative.to_string_lossy().replace('\\', "/")
            ));
        }
    }

    let gathered = to.join(PAGES);
    write(&gathered, &text)?;

    let mut written = written;
    written.push(gathered);
    Ok(written)
}

fn collect(directory: &Path, into: &mut Vec<PathBuf>) -> Result<(), CompileError> {
    let entries = std::fs::read_dir(directory).map_err(|error| io(directory, error))?;
    for entry in entries {
        let entry = entry.map_err(|error| io(directory, error))?;
        let path = entry.path();
        if path.is_dir() {
            collect(&path, into)?;
        } else if path.extension().is_some_and(|extension| extension == "rsx") {
            into.push(path);
        }
    }
    Ok(())
}

fn read(path: &Path) -> Result<String, CompileError> {
    std::fs::read_to_string(path).map_err(|error| io(path, error))
}

fn write(path: &Path, contents: &str) -> Result<(), CompileError> {
    if !changed(path, contents.as_bytes()) {
        return Ok(());
    }
    std::fs::write(path, contents).map_err(|error| io(path, error))
}

/// Whether writing these bytes there would change anything.
///
/// The one question that stands between `rustx dev` and a project it
/// rebuilds for ever. `#[rustx::main]` `include!`s what this crate
/// writes, so cargo records those files as sources of the crate; a file
/// rewritten with the same bytes still gets a new modification date,
/// and cargo then finds the binary older than its sources and rebuilds.
/// That build writes them again. Nothing in the project changed, and
/// the loop never stops.
///
/// A file that cannot be read is a file to write: a missing one, and one
/// whose bytes we are not allowed to see.
pub fn changed(path: &Path, contents: &[u8]) -> bool {
    match std::fs::read(path) {
        Ok(there) => there != contents,
        Err(_) => true,
    }
}

/// Copy `from` over `to`, unless the two already hold the same bytes.
///
/// `std::fs::copy` always writes, and the file it writes is watched —
/// by cargo, when the attribute includes it, and by `rustx dev`, which
/// looks at what the project's files say.
pub fn copy_if_changed(from: &Path, to: &Path) -> std::io::Result<()> {
    let bytes = std::fs::read(from)?;
    if !changed(to, &bytes) {
        return Ok(());
    }
    std::fs::write(to, bytes)
}

fn create_dir(path: &Path) -> Result<(), CompileError> {
    std::fs::create_dir_all(path).map_err(|error| io(path, error))
}

fn io(path: &Path, error: std::io::Error) -> CompileError {
    CompileError {
        offset: 0,
        file: path.to_path_buf(),
        line: 1,
        column: 1,
        message: error.to_string(),
    }
}

/// Where the pages of the application at `manifest` are generated.
///
/// Under the application's own `target/`: outside the source tree, as
/// §7.3 asks, inside the project, which is what `rust-analyzer` needs.
/// Pages were generated in the system's temporary directory before, and
/// everything built — but an editor got nothing from them: a file
/// outside the workspace belongs to no crate, so every hover on a page
/// came back empty. `target/` is also the one directory every Rust
/// project already ignores, and two checkouts of the same project have
/// two of them, so nothing collides.
///
/// It lives here rather than in the attribute macro because three things
/// need the same answer — the macro that includes the file, the tool
/// that writes it, and the language server that hands it to
/// `rust-analyzer` — and a drift between them is a server talking about
/// a file nobody compiles.
pub fn generated_directory(manifest: &Path) -> PathBuf {
    manifest.join("target").join("rustx-pages")
}
